using System;using System.IO;using System.Linq;using System.Text;using System.Drawing;using System.Reflection;using System.Windows.Forms;using CircuitoStudio;
internal static class CalculationProfileTests {
static int n;static void Check(bool ok,string label){n++;if(!ok)throw new Exception(label);}static void Reject(Action action,string label){bool rejected=false;try{action();}catch(InvalidDataException){rejected=true;}Check(rejected,label);}
static Project Fixture(){var p=Project.CreateSample();p.Source.ShortCircuitKA=10;foreach(var c in p.Boards[0].Circuits){c.Cable.AmpacityA=25;c.Cable.Reference="Cabo sintético";c.Protection.BreakingCapacityKA=15;c.Protection.ConventionalTripA=c.BreakerA*1.45;}return p;}
[STAThread]public static int Main(){string dir=Path.Combine(Path.GetTempPath(),"method-profile-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(dir);try{var p=Fixture();string original=CalculationManifest.Describe(p);Check(original.Contains("Perfil não registrado")&&original.Contains(CalculationManifest.EngineId),"legacy project reports current revision without claiming a saved binding");var profile=new CalculationProfile{Standard="Referência de ensaio Ω",Edition="Revisão QA 2026",ReferenceSource="Fonte sintética; sem certificação",Assumptions="Rede radial nominal; sem harmônicos\r\nCondições de ensaio."};var numeric=Engineering.Analyze(p);CalculationManifest.Apply(p,profile);Check(p.CalculationProfile!=profile&&p.CalculationProfile.Engine==CalculationManifest.EngineId,"apply copies profile and binds engine");profile.Edition="Alterada depois";Check(p.CalculationProfile.Edition=="Revisão QA 2026","input edit cannot change preserved profile");var after=Engineering.Analyze(p);Check(numeric.TotalKw==after.TotalKw&&numeric.TotalKvar==after.TotalKvar&&numeric.Circuits.Zip(after.Circuits,(x,y)=>x.CurrentA==y.CurrentA&&x.AccumulatedDropPercent==y.AccumulatedDropPercent&&x.FaultOriginKA==y.FaultOriginKA).All(x=>x),"declaring a standard does not change electrical calculation");string before=EngineeringReport.Memory(p,after);Check(before.Contains("Revisão QA 2026")&&before.Contains("Fonte sintética")&&before.Contains("sem harmônicos")&&before.Contains("Não ativam"),"report records edition source assumptions and declaration boundary");Check(before.Contains("cargas-pq-v1")&&before.Contains("queda-linear-v1")&&before.Contains("fonte-rede-v1")&&before.Contains("protecao-nominal-v1")&&before.Contains("IEEE-754"),"report records versioned methods units and precision");
string project=Path.Combine(dir,"projeto.circuito");p.Save(project);string saved=File.ReadAllText(project);Check(saved.Contains("calculation-profile-v1")&&saved.Contains("\"FileVersion\":4"),"bound profile has guarded capability");var reopened=Project.Load(project);var report=EngineeringReport.Memory(reopened,Engineering.Analyze(reopened));Check(report==before,"complete report and results reproduce exactly after JSON save reopen");for(int i=0;i<3;i++){reopened.Save(project);reopened=Project.Load(project);}Check(EngineeringReport.Memory(reopened,Engineering.Analyze(reopened))==before,"repeated save reopen does not drift results or method");
var unknown=p.CalculationProfile.Copy();unknown.Engine="unknown-future-engine";Reject(delegate{CalculationManifest.Apply(p,unknown);},"unknown revision cannot silently become current");Check(p.CalculationProfile.Engine==CalculationManifest.EngineId,"invalid application preserves bound revision");File.WriteAllText(project,saved.Replace(CalculationManifest.EngineId,"unknown-future-engine"));Reject(delegate{Project.Load(project);},"loading an unsupported revision is rejected");File.WriteAllText(project,saved.Replace("calculation-profile-v1","future-method-v1"));Reject(delegate{Project.Load(project);},"unknown capability rejected");File.WriteAllText(project,saved);string previous=Environment.GetEnvironmentVariable("CIRCUITO_QA_PREVIOUS_EXE");if(!String.IsNullOrWhiteSpace(previous)){var assembly=Assembly.LoadFile(Path.GetFullPath(previous));bool rejected=false;try{assembly.GetType("CircuitoStudio.Project").GetMethod("Load").Invoke(null,new object[]{project});}catch(TargetInvocationException ex){rejected=ex.InnerException is InvalidDataException;}Check(rejected,"actual previous executable rejects unknown profile capability");}
foreach(int missing in new[]{0,1,2}){var bad=p.CalculationProfile.Copy();if(missing==0)bad.Standard="";else if(missing==1)bad.Edition="";else bad.ReferenceSource="";Reject(delegate{CalculationManifest.Apply(p,bad);},"partially declared normative reference rejected");}var none=new CalculationProfile{Assumptions="Nenhuma referência normativa declarada"};none.Validate();Check(CalculationManifest.Describe(new Project{CalculationProfile=none}).Contains("Não definida"),"engine may be bound with no normative reference");var tooLong=p.CalculationProfile.Copy();tooLong.Assumptions=new string('x',10001);Reject(tooLong.Validate,"oversized assumptions rejected");var nul=p.CalculationProfile.Copy();nul.Standard="bad\0text";Reject(nul.Validate,"NUL text rejected");
var gen=Fixture();gen.Source.Model=SourceModel.GeradorSincrono;Check(CalculationManifest.Describe(gen).Contains("fonte-gerador-v1")&&!CalculationManifest.Describe(gen).Contains("fonte-rede-v1"),"generator profile describes actual selected source");gen.Source.Model=SourceModel.UPS;Check(CalculationManifest.Describe(gen).Contains("fonte-ups-v1"),"UPS has its own method and current limit warning");gen.Source.Model=SourceModel.ImpedanciaDefinida;Check(CalculationManifest.Describe(gen).Contains("fonte-rx-v1"),"explicit impedances have own manifest");
string artifacts=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"referencias-metodos");Directory.CreateDirectory(artifacts);p.Save(Path.Combine(artifacts,"origem.circuito"));File.WriteAllText(Path.Combine(artifacts,"memoria.txt"),before,new UTF8Encoding(true));ReportSelection.Save(p,p.Boards[0].Circuits.Select(c=>c.Id),Path.Combine(artifacts,"relatorio.html"),"html");Check(File.ReadAllText(Path.Combine(artifacts,"relatorio.html")).Contains(CalculationManifest.EngineId),"selected report includes revision");
using(var form=new CalculationProfileForm(p)){form.CreateControl();Check(!form.Changed,"opening method form does not bind changes");if(Environment.GetEnvironmentVariable("CIRCUITO_QA_VISUAL")=="1"){form.StartPosition=FormStartPosition.Manual;form.Location=new Point(10,10);form.Show();Application.DoEvents();using(var bitmap=new Bitmap(form.ClientSize.Width,form.ClientSize.Height)){using(var graphics=Graphics.FromImage(bitmap))graphics.CopyFromScreen(form.PointToScreen(Point.Empty),Point.Empty,form.ClientSize);bitmap.Save(Path.Combine(artifacts,"metodos.png"));}form.Hide();}}
Console.WriteLine("PASS: "+n+" calculation-profile assertions");return 0;}catch(Exception ex){Console.Error.WriteLine(ex);return 1;}finally{Directory.Delete(dir,true);}}
}
